def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max(set(x for row in grid for x in row),key=lambda x:sum(row.count(x) for row in grid))
    # Isolated colored markers extend in straight lines toward the nearest
    # non-background edge/object; the marker itself becomes 4.
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v==bg: continue
        # leave long edge/object cells untouched
        if (c==0 or c==w-1 or r==0 or r==h-1): continue
        # find closest non-background cell on same row/column
        options=[]
        for dc in (-1,1):
          x=c+dc
          while 0<=x<w and grid[r][x]==bg: x+=dc
          if 0<=x<w: options.append((abs(x-c), 'h', x))
        for dr in (-1,1):
          y=r+dr
          while 0<=y<h and grid[y][c]==bg: y+=dr
          if 0<=y<h: options.append((abs(y-r), 'v', y))
        if not options: continue
        _,axis,end=min(options)
        # mark point and paint the intervening ray toward the object
        out[r][c]=4
        if axis=='h':
          for x in range(min(c,end)+1,max(c,end)): out[r][x]=v
        else:
          for y in range(min(r,end)+1,max(r,end)): out[y][c]=v
    return out

